@SpringBootApplication
public class BookApiApplication {
  public static void main(String[] args) {
    SpringApplication.run(BookApiApplication.class, args);
  }
}

@Entity
@Table(name = "books")
public class BookEntity {
  @Id
  @GeneratedValue(strategy = GenerationType.IDENTITY)
  private Long id;
  private String title;
  private String author;
  private boolean available = true;

  protected BookEntity() {}
}

public interface BookRepository
    extends JpaRepository<BookEntity, Long> {
  List<BookEntity> findByTitleContainingIgnoreCase(String title);
}

public record CreateBookRequest(
    @NotBlank @Size(max = 200) String title,
    @NotBlank @Size(max = 120) String author
) {}

public record BookResponse(
    long id, String title, String author, boolean available
) {}

@Service
public class BookService {
  private final BookRepository repository;

  public BookService(BookRepository repository) {
    this.repository = repository;
  }

  @Transactional(readOnly = true)
  public BookResponse findById(long id) {
    return repository.findById(id)
        .map(BookMapper::toResponse)
        .orElseThrow(() -> new BookNotFoundException(id));
  }
}

@PostMapping
public ResponseEntity<BookResponse> create(
    @Valid @RequestBody CreateBookRequest request
) {
  BookResponse created = service.create(request);
  URI location = URI.create("/books/" + created.id());
  return ResponseEntity.created(location).body(created);
}

@RestControllerAdvice
public class ApiExceptionHandler {
  @ExceptionHandler(BookNotFoundException.class)
  ResponseEntity<ApiError> notFound(BookNotFoundException error) {
    return ResponseEntity.status(404)
        .body(new ApiError("BOOK_NOT_FOUND", error.getMessage()));
  }
}

@Test
void retourne404QuandLeLivreEstAbsent() throws Exception {
  when(service.findById(99L))
      .thenThrow(new BookNotFoundException(99L));

  mockMvc.perform(get("/books/99"))
      .andExpect(status().isNotFound())
      .andExpect(jsonPath("$.code").value("BOOK_NOT_FOUND"));
}
